import json,re,glob,os
B='/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/'
allr=json.load(open(B+'work-framing/all.json'))
byid={r['id']:r for r in allr}
claimed={};rej={}
for f in glob.glob(B+'features/*.json'):
    if f.endswith('framing.json'): continue
    d=json.load(open(f))
    for x in d['features']:
        for i in x['raw_ids']: claimed.setdefault(i,[]).append(d['section']+'/'+x['id'])
    for x in d['rejected']:
        rej.setdefault(x['raw_id'],[]).append(d['section']+': '+x['reason'])
print('--- area framing claimed or rejected elsewhere')
for r in allr:
    if r['area']=='framing' and (r['id'] in claimed or r['id'] in rej):
        print(r['id'],r['name'],'| C',claimed.get(r['id'],''),'| R',rej.get(r['id'],''))
print('--- rejected as belongs to framing, by id')
seen=[]
for i,v in rej.items():
    if any('framing' in x for x in v):
        seen.append(i)
        print(i,byid.get(i,{}).get('area'),byid.get(i,{}).get('name'),v,claimed.get(i,''))
print(len(seen))
print('--- taxonomy pages matching')
t=json.load(open(B+'taxonomy.json'))
for s in t['sections']:
    for p in s['pages']:
        if re.search(r'hide|silent|remove background|cutout|behind subject|auto zoom|shortcut overlay|analy|camera|re-lay|relay|vertical',p['title']+' '+p['scope'],re.I):
            print(s['id'],p['slug'],'|',p['title'],'|',p['scope'][:160])

