3	/// File ▸ Make Vertical Version… (road map "creator-jobs" VR3b, spec §11 VR-39) — the menu door
4	/// over VR3a's step (`VerticalVersion.plan`) and copy (`ProjectDocument.verticalCopy`): the
5	/// sheet (`VerticalVersionSheetController`), and its hand-off — the Analyzing sheet when an
6	/// analysis is missing, then the copy opened in front or the step applied in place as one undo
7	/// step "Make Vertical". `make_vertical_version` is the mirror (`AgentServer+VerticalVersion.swift`).
8	///
9	/// The sheet never edits. Its hand-off is not an AppKit event, so the step in place goes through
10	/// `performGroupedEdit` (Follow Subject's shape), and only onto the project handle and scope the
11	/// sheet read: a changed project is refused before anything is made, again when the Analyzing
12	/// sheet lands, and again after the subjects are read off main. Stop is the Analyzing sheet's
13	/// own and makes nothing. A Speaker hand-off is not made after its analysis lands: the sheet is
14	/// presented again from it, so a person confirms each microphone's face before Make (road map
15	/// creator-jobs VR6b, spec §11 VR-66 (e)). Every refusal beeps and puts its sentence at the inspector's foot
16	/// (spec §11 CI-10).
17	extension EditorViewController {
18	
19	    @objc func showVerticalVersionSheet(_ sender: Any?) {
20	        guard let document, validateVerticalVersionAction(#selector(showVerticalVersionSheet(_:)))
21	            == true
22	        else {
23	            NSSound.beep()
24	            return
25	        }
26	        presentVerticalSheet(document: document, restoring: nil)
27	    }
28	
29	    /// The sheet, fresh or presented again from a Speaker hand-off whose analysis landed.
30	    private func presentVerticalSheet(document: ProjectDocument, restoring: VerticalHandOff?) {
31	        presentAsSheet(
32	            VerticalVersionSheetController(document: document, restoring: restoring) {
33	                [weak self, weak document] handOff in
34	                guard let self, let document else { return }
35	                self.analyzeForVertical(handOff, document: document)
36	            })
37	    }
38	
39	    /// The sheet's hand-off: refused when the project or scope changed since the sheet read it;
40	    /// else committed at once, or the Analyzing sheet over every missing request, one row each.
41	    private func analyzeForVertical(_ handOff: VerticalHandOff, document: ProjectDocument) {
42	        guard document.project === handOff.asked, document.scope == handOff.scope else {
43	            refuseVertical(
44	                handOff.requests.isEmpty ? Self.verticalSheetChanged : Self.verticalChanged,
45	                document: document)
46	            return
47	        }
48	        guard !handOff.requests.isEmpty else {
49	            commitVertical(handOff, subjects: handOff.subjects, document: document)
50	            return
51	        }
52	        guard view.window?.attachedSheet == nil else {
53	            NSSound.beep()
54	            return
55	        }
56	        let rows = handOff.requests.map {
57	            AnalyzingSheetController.Row(name: FollowSubject.rowName($0), request: $0)
58	        }
59	        presentAsSheet(
60	            AnalyzingSheetController(
61	                document: document, command: VerticalVersion.actionName, rows: rows
62	            ) { [weak self, weak document] outcome in
63	                guard let self, let document else { return }
64	                self.finishVertical(outcome, rows: rows, handOff: handOff, document: document)
65	            })
66	    }
67	
68	    /// The Analyzing sheet's answer: refused when the project or scope changed, a failed
69	    /// analysis named; else the subjects read off main, checked again, and committed.
70	    private func finishVertical(
71	        _ outcome: AnalyzingSheetController.Outcome, rows: [AnalyzingSheetController.Row],
72	        handOff: VerticalHandOff, document: ProjectDocument
73	    ) {
74	        guard document.project === handOff.asked, document.scope == handOff.scope else {
75	            refuseVertical(Self.verticalChanged, document: document)
76	            return
77	        }
78	        switch outcome {
79	        case .failed(let name, let why):
80	            let request = rows.first { $0.name == name }?.request
81	            let kind = request?.kind.rawValue ?? "framing"
82	            let file = request?.media.name ?? name
83	            refuseVertical("The \(kind) analysis of “\(file)” failed: \(why).", document: document)
84	        case .landed:
85	            if handOff.settings.follow == .speaker {
86	                // VR-66 (e): the faces are confirmed on the sheet, never made here.
87	                guard view.window?.attachedSheet == nil else {
88	                    NSSound.beep()
89	                    return
90	                }
91	                presentVerticalSheet(document: document, restoring: handOff)
92	                return
93	            }
94	            guard let cacheDir = document.cacheDirectory else {
95	                refuseVertical(
96	                    ProjectDocument.AnalysisRequestError.noCache.localizedDescription,
97	                    document: document)
98	                return
99	            }
100	            let targets = handOff.targets
101	            let cursor = handOff.cursor
102	            let asked = handOff.asked
103	            DispatchQueue.global(qos: .userInitiated).async { [weak self, weak document] in
104	                var subjects = FollowSubject.subjects(targets, in: asked, cacheDir: cacheDir)
105	                // A cursor beside the analysis (spec §11 VR-51).
106	                subjects.merge(FramingCursor.subjects(cursor, in: asked)) { _, new in new }
107	                DispatchQueue.main.async {
108	                    guard let self, let document else { return }
109	                    guard document.project === handOff.asked, document.scope == handOff.scope
