3	/// The path Clip ▸ Camera Layout ▸ and the Picture sub-tab's Layout section share (road map
4	/// creator-jobs CO7, spec §11 CO-70, CO-72): the camera's focus read from its cached person
5	/// masks, the trial, then the commit or the nest offer. `keepsFocus` is the nested-camera test
6	/// the offer and `switch_layout`'s tool share.
7	enum CameraLayoutCommand {
8	    static let actionName = "Camera Layout"
9	
10	    /// `choice` at the playhead for these roles. With the camera's masks cached for every
11	    /// frame it plays, the focus is read on `CameraLayoutFocus.queue` and the switch applied on
12	    /// main only if the project and scope are unchanged (else a beep and nothing changed);
13	    /// without them it runs at once. Main thread.
14	    static func run(
15	        _ choice: CameraLayoutChoice, camera: UInt32, screen: UInt32?, duration: Ticks?,
16	        document: ProjectDocument, window: NSWindow?
17	    ) {
18	        let at = document.playhead
19	        guard let inputs = CameraLayoutFocus.inputs(camera: camera, in: document) else {
20	            switchLayout(
21	                choice, camera: camera, screen: screen, at: at, duration: duration, focus: nil,
22	                document: document, window: window)
23	            return
24	        }
25	        let project = document.project
26	        let scope = document.scope
27	        CameraLayoutFocus.queue.async {
28	            let focus = CameraLayoutFocus.focus(inputs)
29	            DispatchQueue.main.async { [weak document, weak window] in
30	                guard let document else { return }
31	                guard document.project === project, document.scope == scope else {
32	                    NSSound.beep()
33	                    return
34	                }
35	                switchLayout(
36	                    choice, camera: camera, screen: screen, at: at, duration: duration,
37	                    focus: focus, document: document, window: window)
38	            }
39	        }
40	    }
41	
42	    /// The trial, then the offer or the commit (CO-72).
43	    private static func switchLayout(
44	        _ choice: CameraLayoutChoice, camera: UInt32, screen: UInt32?, at: Ticks,
45	        duration: Ticks?, focus: (Double, Double)?, document: ProjectDocument, window: NSWindow?
46	    ) {
47	        let op = choice.op(
48	            camera: camera, screen: screen, at: at, duration: duration, focus: focus)
49	        if let window, case .refused(let refusal)? = try? document.project.applying(
50	            [addressed(op, document)])
51	        {
52	            var nested = choice.op(
53	                camera: camera, screen: screen, at: at, duration: duration, focus: focus,
54	                nest: true)
55	            if case .applied? = try? document.project.applying([addressed(nested, document)]) {
56	                if focus != nil, !keepsFocus(nested: nested, camera: camera, document: document) {
57	                    nested = choice.op(
58	                        camera: camera, screen: screen, at: at, duration: duration, nest: true)
59	                }
60	                LayoutOfferSheet.present(
61	                    refusal: refusal, nested: nested, document: document, window: window)
62	                return
63	            }
64	        }
65	        document.performGroupedEdit(actionName, [op])
66	    }
67	
68	    /// `nested` carries `nest: true` and the filled focus. Trials it on `document.project`,
69	    /// scoped as `ProjectDocument.addressed` scopes it. False only when the trial applies and
70	    /// the camera id is absent from the applied project's view (`scope.flatMap { p.scoped($0) }
71	    /// ?? p`, then `snapshot.clip(camera) == nil`), i.e. the nest replaced the camera with a
72	    /// nest clip, where a focus in the camera media's pixels would miss (CO-70). Main thread.
73	    static func keepsFocus(nested: ReelOp, camera: UInt32, document: ProjectDocument) -> Bool {
74	        let op = addressed(nested, document)
75	        guard case .applied(let applied)? = try? document.project.applying([op]) else {
76	            return true
77	        }
78	        let view = op.scope.flatMap { applied.scoped($0) } ?? applied
79	        return view.snapshot.clip(camera) != nil
80	    }
81	
82	    /// `ProjectDocument.addressed`'s rule for one op: the open nest stamped on an op that is not
83	    /// document-level and carries no scope of its own.
84	    private static func addressed(_ op: ReelOp, _ document: ProjectDocument) -> ReelOp {
85	        op.isDocumentLevel || op.scope != nil ? op : op.scoped(document.scope)
86	    }
87	}
